package Jumbl;

import java.util.*;

/**
 * The parser goes through the tokens generated by the Lexer 
 * and makes operations out of it.
 * 
 * A lot of the code is adapted from the book CraftingInterpreters
 * not all my original work
 */
public class Parser
{
    private ArrayList<Token> tokens; // arraylist of tokens generated by lexer
    private int idx; // token index
    public Token cur; // current token

    public Parser(ArrayList<Token> tokens){ // constructor
        this.tokens=tokens;
        idx=-1;
        advance();
    }
    public Token advance(){ // moves forward through tokens
        idx++;
        if(idx<tokens.size())cur=tokens.get(idx); // arraylist stuff
        return cur;
    }
    private boolean match(String[] types){
        for(String type : types){
            if(check(type)){
                advance();
                return true;
            }
        }
        return false;
    }
    private boolean check(String type){
        if(idx==tokens.size())return false;
        return (Objects.equals(cur.getType(), type)); 
    }
    public static Stack<Stmt> reverse(Stack<Stmt> s){
        Stack<Stmt> newS = new Stack<Stmt>(); 
        while(!s.empty())newS.push(s.pop());
        return newS;
    } // i could really should have just used a queue
    private Stmt getDaughter(Stmt parent){
        Stmt.BlockStmt dStmt = null;
        if(cur.getType().equals("ELIF")){
            Stack<Stmt> dStmts = null;
            advance();
            Expr nExpr = expression();
            dStmt = new Stmt.BlockStmt("elif", parent);
            if(cur.getType().equals("LSQUIG")) {
                advance();
                dStmts = statement(dStmt);
            }
            advance();
            dStmt.addStmts(dStmts);
            dStmt.addExpr(nExpr);
            dStmt.addDaughter(getDaughter(dStmt));
            return dStmt;
        }
        if(cur.getType().equals("ELSE")){
            Stack<Stmt> dStmts = null;
            advance();
            dStmt = new Stmt.BlockStmt("else", parent);
            if(cur.getType().equals("LSQUIG")) {
                advance();
                dStmts = statement(dStmt);
            }
            dStmt.addStmts(dStmts);
            return dStmt;
        }
        return dStmt;
    }
    private HashMap<Value, String> makeParams(){
        HashMap<Value, String> rtnr = new HashMap<Value, String>();
        do{
            advance();
            String name = cur.value;
            advance();
            Value var = new Value.Var(cur.value);
            rtnr.put(var, name);
            advance();
        }while(cur.getType().equals("COMMA"));
        return rtnr;
    } // i think this is supposed to be used for making functions
    /**
     * The main parse function, recursively descends through the token list to create an abstract syntax tree
     **/
    public void parse(){
        makeGlobalStuff();
    }
    /**WARNING: RECURSIVE DESCENT PARSING BELOW THIS POINT**/
    private void makeGlobalStuff(){
        ArrayList<Stmt> globals = new ArrayList<Stmt>();
        while(idx<tokens.size()){
            if(check("EXEC")){
                advance();
                Stack<Stmt> stmts = null;
                Memory.exec = new CodeUnit.Exec();
                if(cur.getType().equals("LSQUIG")){ // error if there isnt
                    advance();
                    stmts = statement(Memory.exec.execStmt);
                }
                Memory.exec.addStmts(stmts);
                advance();
            }
            advance();
        }
    }
    private Stack<Stmt> statement(Stmt parent){
        Stack<Stmt> s = new Stack<Stmt>();
        while(!cur.getType().equals("RSQUIG")){
            if(check("WRITE")){
                advance();
                Expr expr = expression();
                Stmt stmt = new Stmt.BinaryStmt.Write(expr);
                s.push(stmt);
            }
            else if(check("WRITELN")){
                advance();
                Expr expr = expression();
                Stmt stmt = new Stmt.BinaryStmt.WriteLine(expr);
                s.push(stmt);
            }
            else if(check("DEC")){
                advance();
                String name = cur.value;
                advance();
                Stmt stmt = null;
                if(cur.getType().equals("EQUAL")){
                    advance();
                    stmt = new Stmt.BinaryStmt.Dec(name, expression());
                }
                s.push(stmt);
            }
            else if(check("IF")){
                advance();
                Expr expr = expression();
                //advance();
                Stack<Stmt> stmts = null;
                Stmt.BlockStmt pushable = new Stmt.BlockStmt("if",parent);
                if(cur.getType().equals("LSQUIG")){
                    advance();
                    stmts = statement(pushable);
                }
                advance();
                pushable.addExpr(expr);
                pushable.addStmts(stmts);
                pushable.addDaughter(getDaughter(parent));
                s.push(pushable);
            }
            else if(check("VARIABLE")){
                Value v = tokens.get(idx).toValue();
                advance();
                if(cur.getType().equals("LPAREN")){
                    ArrayList<Expr> inputs = new ArrayList<Expr>();
                    do{
                        advance();
                        inputs.add(expression());
                        //advance();
                    }while(cur.getType().equals("COMMA"));
                    s.push(new Stmt.BinaryStmt.FuncOp(v, inputs));
                    advance();
                }
                else {
                    Token op = cur;
                    advance();
                    Expr right = expression();
                    Expr expr = new Expr.Binary.VarOp(v, op, right);
                    s.push(new Stmt.BinaryStmt.VarOp((new Expr.Binary.VarOp(v, op, right))));
                }
            }
            else if(check("LOOP")){
                advance();
                Stack<Stmt> stmts = null;
                Stmt.BlockStmt pushable = new Stmt.BlockStmt("LOOP", parent);
                if(cur.getType().equals("LSQUIG")){
                    advance();
                    stmts = statement(pushable);
                }
                advance();
                if(check("WHILE")){
                    advance();
                    Expr expr = expression(); // add check for whether this is a boolean expression
                    pushable.addStmts(stmts);
                    pushable.addExpr(expr);
                    s.push(pushable);
                }
            }
        }

        return reverse(s); // expected stmt error if null
    }
    private Expr expression() {return equality();}
    private Expr equality() {
        Expr expr = comparison();
        String[] s = {"NOTE", "EE"};

        while (match(s)){
            Token op = tokens.get(idx-1);
            Expr right = comparison();
            expr = new Expr.Binary(expr, op, right);
        }

        return expr;
    }
    private Expr comparison() {
        Expr expr = term();
        String[] s = {"GREATE", "LESSE", "GREAT", "LESS"};
        while (match(s)){
            Token op = tokens.get(idx-1);
            Expr right = term();
            expr = new Expr.Binary(expr, op, right);
        }

        return expr;
    }
    private Expr term(){
        Expr expr = factor();
        String[] s = {"PLUS", "MINUS"};
        while (match(s)){
            Token op = tokens.get(idx-1);
            Expr right = factor();
            expr = new Expr.Binary(expr, op, right);
        }

        return expr;
    }
    private Expr factor(){
        Expr expr = unary();
        String[] s = {"MUL", "DIV"};
        while (match(s)){
            Token op = tokens.get(idx-1);
            Expr right = unary();
            expr = new Expr.Binary(expr, op, right);
        }

        return expr;
    }
    private Expr unary(){
        String[] s = {"NOT"};
        if (match(s)){
            Token op = tokens.get(idx-1);
            Expr right = expression();
            return new Expr.Unary(op, right);
        }
        s[0] = "MINUS";
        if (match(s)){
            Token op = tokens.get(idx-1);
            Expr right = unary();
            return new Expr.Unary(op, right);
        }

        return primary();
    }

    private Expr primary(){ 
        String[] s = {"TRUE"}; // this is really stupid and needs to be fixed
        if(match(s)) return new Expr.Literal(new Value.Bool(true));
        s[0] = "FALSE";
        if(match(s)) return new Expr.Literal(new Value.Bool(false));
        //         s[0] = "NULL";
        //         if(match(s)) return new Expr.Literal(new Value.Null(null));
        s[0] = "INT";
        if(match(s)){
            return new Expr.Literal(new Value.Int(tokens.get(idx-1).toValue().i));
        }
        s[0]= "DOUB";
        if(match(s)){
            return new Expr.Literal(new Value.Doub(tokens.get(idx-1).toValue().d));
        }
        s[0] = "STRING";
        if(match(s)) return new Expr.Literal(new Value.Str(tokens.get(idx-1).toValue().s));
        s[0] = "VARIABLE";
        if(match(s)) return new Expr.Literal(new Value.Var(tokens.get(idx-1).toValue().s));

        s[0] = "LPAREN";
        if(match(s)){
            Expr expr = expression();
            if(findRPAREN()){advance();return new Expr.Grouping(expr);}
        }
        return null; /******* MAKE NULL ERROR *******/
    }

    /**
    finds the next ')'
     */
    private boolean findRPAREN(){ // this is actually mine
        for(int i = idx;i<tokens.size();i++){
            if(tokens.get(idx).getType().equals("RPAREN"))return true;
        }
        return false;
    }

}
